off<Key extends keyof Events>(type: Key, handler?: GenericEventHandler) {
	const handlers: Array<GenericEventHandler> | undefined = all!.get(type);
	if (handlers) {
		if (handler) {
			handlers.splice(handlers.indexOf(handler) >>> 0, 1);
		} else {
			all!.set(type, []);
		}
	}
},

export interface Emitter<Events extends Record<EventType, unknown>> {
	all: EventHandlerMap<Events>;

	on<Key extends keyof Events>(type: Key, handler: Handler<Events[Key]>): void;
	on(type: '*', handler: WildcardHandler<Events>): void;

	off<Key extends keyof Events>(
		type: Key,
		handler?: Handler<Events[Key]>
	): void;
	off(type: '*', handler: WildcardHandler<Events>): void;

	emit<Key extends keyof Events>(type: Key, event: Events[Key]): void;
	emit<Key extends keyof Events>(
		type: undefined extends Events[Key] ? Key : never
	): void;
}

it('off("type") should remove all handlers of the given type', () => {
	inst.on('foo', () => {});
	inst.on('foo', () => {});
	inst.on('bar', () => {});
	inst.off('foo');
	expect(events.get('foo')).to.deep.equal([]);
	expect(events.get('bar')).to.have.length(1);
	inst.off('bar');
	expect(events.get('bar')).to.deep.equal([]);
});

it('should remove handler for type', () => {
	const foo = () => {};
	inst.on('foo', foo);
	inst.off('foo', foo);

	expect(events.get('foo')).to.be.empty;
});

export type WildcardHandler<T = Record<string, unknown>> = (
	type: keyof T,
	event: T[keyof T]
) => void;

on<Key extends keyof Events>(type: Key, handler: GenericEventHandler) {
	const handlers: Array<GenericEventHandler> | undefined = all!.get(type);
	if (handlers) {
		handlers.push(handler);
	} else {
		all!.set(type, [handler] as EventHandlerList<Events[keyof Events]>);
	}
},

it('should remove only the first matching listener', () => {
	const foo = () => {};
	inst.on('foo', foo);
	inst.on('foo', foo);
	inst.off('foo', foo);
	expect(events.get('foo')).to.deep.equal([foo]);
	inst.off('foo', foo);
	expect(events.get('foo')).to.deep.equal([]);
});

emit<Key extends keyof Events>(type: Key, evt?: Events[Key]) {
	let handlers = all!.get(type);
	if (handlers) {
		(handlers as EventHandlerList<Events[keyof Events]>)
			.slice()
			.map((handler) => {
				handler(evt!);
			});
	}

	handlers = all!.get('*');
	if (handlers) {
		(handlers as WildCardEventHandlerList<Events>)
			.slice()
			.map((handler) => {
				handler(type, evt!);
			});
	}
}

